import functools

from taf.ul.bts_components import Smod
from robot.libraries.BuiltIn import BuiltIn
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output
from taf.rfrl.l3_call.connection.ssh_connection.ssh_connection import SshConnection
from taf.internal.aliasing import AliasLookupError


def restore_smod_connection_if_lost(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            func(self, *args, **kwargs)

        except AliasLookupError:
            self._connect_to()
            func(self, *args, **kwargs)

    return wrapper


class ClassicalSshConnection(SshConnection):

    def __init__(self, node="gnb"):
        super(ClassicalSshConnection, self).__init__()
        self.smod = Smod()
        self._node = node

    def _connect_to(self):
        self.smod.connect_to(*self._get_details_to_login())

    def _close_connection(self):
        self.smod.close_connection()

    def _send_command(self, command, timeout=None):
        self.smod.send_command(command=command, timeout=timeout)

    def _execute(self, command, timeout=None):
        return self.smod.execute(command=command, timeout=timeout)

    def _start_tcpdump(self, file_path):
        return self.smod.start_tcpdump(file_path=file_path)

    @restore_smod_connection_if_lost
    def _stop_tcpdump(self):
        self.smod.stop_tcpdump_by_pid(self._tcpdump_pid)

    def _download_file(self, remote_path, local_path):
        self.smod.download_file(local_path=local_path, remote_path=remote_path)

    @log_input_and_output
    def _get_details_to_login(self, bts_id=0):
        tl = BuiltIn().get_variable_value("${tl}")

        if self._node == "gnb":
            airscale = tl.gnbs[bts_id].dus[0].airscale
        else:
            airscale = tl.enbs[bts_id].airscale

        units = getattr(airscale, "common_units", None) or getattr(airscale, "core_units", None)
        details_to_login = units[0].lmp_connection

        return details_to_login.addr, details_to_login.username, details_to_login.password

    def _clean_up_environment_after_tcpdump_collection(self, remote_path):
        splitted_path = remote_path.split("/")
        folder, filename = "/".join(splitted_path[:-1]), splitted_path[-1]
        self.smod.send_command(command="find {} -name '{}' -delete".format(folder, filename))
